// ============================================================
// AIDL Juniors — ROUTE-MAP MODULE LESSONS · ROAD CREW pack
// Uses the generator in junior-lessons-modules.js (load that first).
// IDs TM-01…TM-34 (ranged modules use their first number).
// ============================================================

window.AIDL_JR_REGISTER_MODULES({
  level: 'T', prefix: 'TM-', total: 34, tierName: 'Road Crew', ages: '12\u201316',
  instructor: 'PROF. RAGGA', instructorRole: 'SPECIALIST \u00b7 AUDITS & PROMPTING \u00b7 CLASS T',
  hi: 'Prof. Ragga here.',
  sems: [
    { name: 'Under the Hood', mods: [
      { n: 1, name: 'The AI Landscape Audit', act: 'Log every AI touchpoint in your week; the class builds a \u201clocal AI map\u201d.', hook: '\u27e8Local apps, gov services, shops, transit\u27e9', actShort: 'Audit a week of AI touchpoints',
        sign: 'rect', glyph: 'AUDIT', h: 'You touch AI more than you think', lt: 'LANDSCAPE AUDIT',
        p: ['Recommenders pick your videos, banks score transactions, transit apps predict arrivals, cameras read plates. Week one\u2019s job: <strong>log every touchpoint</strong> \u2014 what system, what it decides, what data it likely uses.', 'Merged into a class <strong>local AI map</strong>, the log becomes evidence: where AI already runs your town, visibly or invisibly. Auditing starts with seeing.'],
        ex: { t: 'Touchpoint log fields', i: ['g|System: what and where (feed, bank, transit, shop)', 'g|Decision: what it chose for/about you', 'g|Data: what it probably used', 'b|\u201cI don\u2019t use AI\u201d \u2014 the log will disagree'] },
        co: ['Auditor\u2019s stance', 'Neither fan nor doomer. An auditor documents what IS \u2014 judgement comes after evidence.'],
        sort: { name: 'VISIBLE OR INVISIBLE?', prompt: 'Sort the AI touchpoints:', g: 'VISIBLE \u2014 YOU CHOSE IT \ud83d\udfe2', r: 'INVISIBLE \u2014 RUNS ON YOU \ud83d\udd34', intro: 'GREEN = you knowingly used it. RED = it processed you without an ask.', items: ['Asking a chatbot for revision help|green', 'A feed ranking what you see next|red', 'Voice assistant setting a timer|green', 'Shop camera analytics counting you|red', 'Translating a phrase yourself|green', 'Your loan-worthiness being scored|red', 'A plate reader logging the family car|red'] },
        quiz: { q: 'Why do invisible touchpoints matter MORE to an auditor than visible ones?', o: ['A|They don\u2019t \u2014 visible ones are bigger', 'B|No consent, no awareness, no appeal \u2014 decisions happen about you without you|1', 'C|Because they\u2019re newer'], rf: 'Consent and appeal are the auditor\u2019s compass. Invisible systems have neither by default.', wf: 'Size isn\u2019t the issue \u2014 <b>consent</b> is. Invisible systems decide about you without awareness or appeal.' },
        learned: 'How to audit an AI landscape: log <b>system, decision, data</b> per touchpoint, and split visible from invisible.', take: 'Keep the log running all semester \u2014 the Bias Hunt (M9) and Privacy Engineering (M13) will mine it.' },
      { n: 2, name: 'Data Is the Fuel', act: 'Collect a real class dataset \u2014 e.g. 200 photos of local street objects. Label it; discover labeling disagreements.', hook: 'The dataset is \u27e8local by construction\u27e9', actShort: 'Build and label a real 200-photo dataset',
        sign: 'rect', glyph: 'DATA', h: 'Datasets are made, not found', lt: 'DATA IS THE FUEL',
        p: ['Every model eats one thing: <strong>labeled data</strong>. Today the class makes some \u2014 200 photos of local street objects, labeled by hand. Then the discovery every data scientist makes: <strong>you disagree</strong>. Is that a \u201ccart\u201d or a \u201cstall\u201d? A \u201cpath\u201d or a \u201croad\u201d?', 'Those disagreements aren\u2019t noise \u2014 they\u2019re the human choices baked into every dataset on Earth. Whoever labels, decides what the model will believe.'],
        ex: { t: 'Dataset-building truths', i: ['g|A labeling GUIDE before labeling \u2014 or chaos', 'g|Two labelers per photo exposes disagreement', 'g|Edge cases (cart-stall hybrids) deserve their own list', 'b|\u201cThe data speaks for itself\u201d \u2014 no; labelers spoke first'] },
        co: ['Power check', 'Whoever writes the labels writes the model\u2019s worldview. Remember that when the dataset is about PEOPLE.', true],
        build: 'Design the class dataset. PERSONA: you\u2019re the dataset lead for a street-object classifier. REQUEST: define what to photograph and your labeling guide (categories + tie-breaker rules). OUTPUT: category list + 3 rules for hard cases. CHECK: how you\u2019ll measure labeler disagreement and what % is acceptable.',
        quiz: { q: 'Two classmates label the same 40 photos and disagree on 9. What does this reveal?', o: ['A|One of them is bad at labeling', 'B|Labels encode human judgement \u2014 categories need clearer rules, and some ambiguity is real|1', 'C|The photos are broken'], rf: 'Disagreement is data ABOUT the labels. Tighten the guide, keep an edge-case list \u2014 and stay humble.', wf: 'Nobody\u2019s \u201cbad\u201d \u2014 labels are <b>judgement calls</b>. The fix is clearer rules plus an honest edge-case list.' },
        learned: 'Datasets are <b>constructed</b>: labeling guides, human disagreement, and edge cases decide what a model will believe.', take: 'This dataset trains Module 3\u2019s model. Guard the labeling guide \u2014 it\u2019s the model\u2019s constitution.' },
      { n: 3, name: 'Train / Test / Break', act: 'Train an image or sound classifier; hold out a test set; adversarial \u201cbreak day\u201d.', hook: '\u27e8Local objects, dialect words, bird calls\u27e9', actShort: 'Train, hold out a test set, then attack',
        sign: 'circle', glyph: 'T/T/B', h: 'Never grade a model on its homework', lt: 'TRAIN / TEST / BREAK',
        p: ['Split your dataset: <strong>train</strong> on most of it, <strong>test</strong> on photos the model never saw. Testing on training data is like grading students on questions they memorized \u2014 flattering, meaningless.', 'Then break day: hunt inputs that fool it. Odd angles, half-shadows, look-alike objects. Every break is a found <strong>failure mode</strong> \u2014 better found by you than by a user.'],
        ex: { t: 'The three-day protocol', i: ['g|Day 1 TRAIN: ~80% of the data', 'g|Day 2 TEST: held-out 20% \u2014 the honest score', 'g|Day 3 BREAK: adversarial hunting, points per fool', 'b|Testing on training photos \u2014 the classic self-deception'] },
        co: ['Break day ethics', 'Attack the MODEL, not each other\u2019s work. Every failure found is a gift to the team.'],
        quiz: { q: 'Model scores 98% on training photos, 71% on the held-out test set. Which number tells the truth?', o: ['A|98% \u2014 it\u2019s higher', 'B|71% \u2014 unseen data is the only honest exam|1', 'C|Average them: 84.5%'], rf: 'The gap between 98 and 71 even has a name \u2014 overfitting: memorizing homework instead of learning.', wf: 'Higher \u2260 truer. Unseen data is the only honest exam \u2014 <b>71%</b>. The 27-point gap is overfitting.' },
        sort: { name: 'FAIR TEST OR CHEAT?', prompt: 'Sort the evaluation moves:', g: 'HONEST EVALUATION \ud83d\udfe2', r: 'SELF-DECEPTION \ud83d\udd34', intro: 'GREEN = the score means something. RED = flattering yourself.', items: ['Testing on photos held out from training|green', 'Testing on the training photos|red', 'Reporting the score on the hardest category too|green', 'Deleting test photos the model gets wrong|red', 'Break-day inputs from OUTSIDE the dataset|green', 'Retesting until a lucky split scores high|red'] },
        learned: 'The honest ML loop: <b>train / held-out test / adversarial break</b> \u2014 and why training-set scores lie (overfitting).', take: 'Ask of every AI claim you ever hear: \u201ctested on WHAT? seen or unseen?\u201d' },
      { n: 4, name: 'How Models Learn', act: 'Unplugged math: gradient-descent hill-walking game; decision trees on paper with local decision problems.', hook: '\u201cShould the market open early?\u201d tree with \u27e8local weather & festival features\u27e9', actShort: 'Walk gradient descent; grow a paper tree',
        sign: 'triangle', glyph: '\u2193', h: 'Learning = getting less wrong, step by step', lt: 'HOW MODELS LEARN',
        p: ['Blindfolded on a hillside, wanting the valley: feel the slope, step downhill, repeat. That\u2019s <strong>gradient descent</strong> \u2014 the model measures its error, nudges its numbers to shrink it, and repeats a million times. \u201cLearning\u201d is just error, going downhill.', 'Second machine: the <strong>decision tree</strong> \u2014 a stack of yes/no questions. \u201cRaining? Festival week? \u2192 open the market late.\u201d You\u2019ll grow one on paper for a real local decision.'],
        ex: { t: 'Two learners, unplugged', i: ['g|Gradient descent: feel slope \u2192 step \u2192 repeat', 'g|Decision tree: best question first, split, repeat', 'g|Both minimize WRONGNESS, nothing mystical', 'b|\u201cThe AI understood\u201d \u2014 no; the error went downhill'] },
        co: ['Local minimum trap', 'Sometimes the hill-walker settles in a small dip that isn\u2019t the deepest valley. Even the math has humility built in.'],
        build: 'Grow a paper decision tree. PERSONA: market committee\u2019s data advisor. REQUEST: decide \u201copen early or late?\u201d using local features (weather, festival, day, season). OUTPUT: a tree of 3\u20134 yes/no questions, most useful question at the top. CHECK: test it against 5 real remembered days \u2014 how often is it right?',
        quiz: { q: 'In the hill-walking game, what does \u201cdownhill\u201d actually represent?', o: ['A|Less error \u2014 predictions getting less wrong|1', 'B|The model getting physically smaller', 'C|Running out of data'], rf: 'Height = error. Every training step is one nudge downhill on the wrongness landscape.', wf: 'The hill is <b>error</b>. Downhill = less wrong. Training is a million tiny downhill nudges.' },
        learned: 'Two learning machines demystified: <b>gradient descent</b> (error downhill) and <b>decision trees</b> (best questions first).', take: 'When someone says \u201cthe AI understands\u201d, translate: \u201cits error went downhill on past examples.\u201d Keeps you honest.' },
      { n: 5, name: 'Generative AI Demystified', act: 'Next-word prediction game, then LLM anatomy: tokens, training data, temperature.', hook: 'Predict-the-next-word with \u27e8local song lyrics / proverbs\u27e9 to expose data gaps', actShort: 'Play next-word; meet tokens & temperature',
        sign: 'circle', glyph: 'LLM', h: 'A very fancy autocomplete', lt: 'GENERATIVE AI',
        p: ['Play the game: \u201cThe cat sat on the ___\u201d \u2014 easy. Now a local proverb: the class wins, the machine flops. Why? LLMs predict the <strong>next token</strong> from patterns in training text \u2014 and your proverbs barely appear there.', 'Anatomy in three parts: <strong>tokens</strong> (word-pieces it predicts), <strong>training data</strong> (whose text taught it \u2014 hence the gaps), <strong>temperature</strong> (dial from predictable to wild). Fluent \u2260 knowing. It\u2019s statistics wearing a smooth voice.'],
        ex: { t: 'LLM anatomy', i: ['g|Tokens: text chopped into pieces, predicted one by one', 'g|Training data: mostly big internet languages \u2014 your gap, exposed', 'g|Temperature: low = safe and samey, high = creative and risky', 'b|\u201cIt knows things\u201d \u2014 it models what text tends to say'] },
        co: ['The demystifying question', 'Ask of any chatbot marvel: \u201cwhat text would make this the LIKELY next thing to say?\u201d The magic evaporates \u2014 usefully.'],
        quiz: { q: 'The LLM completes English rhymes perfectly but butchers your local song. The reason?', o: ['A|It dislikes the song', 'B|Its training text barely contains your language \u2014 prediction needs patterns it never saw|1', 'C|Songs can\u2019t be predicted'], rf: 'Prediction quality tracks training data. Your language\u2019s absence is measurable \u2014 you just measured it.', wf: 'No feelings involved \u2014 it predicts from <b>training text</b>, and your language barely appears there. A data gap, made visible.' },
        sort: { name: 'WHAT\u2019S REALLY HAPPENING?', prompt: 'Sort the claims about a chatbot:', g: 'ACCURATE PICTURE \ud83d\udfe2', r: 'MYTH \ud83d\udd34', intro: 'GREEN = how LLMs actually work. RED = folklore.', items: ['It predicts likely next tokens|green', 'It looks up facts in a truth database|red', 'Fluent output can still be false|green', 'It understands like a person|red', 'Its skills mirror its training text|green', 'It gets smarter each time you chat|red'] },
        learned: 'LLMs = <b>token prediction over training text</b>, tuned by temperature \u2014 fluent, gap-ridden, and not a knower.', take: 'Module 6 weaponizes this: if it predicts rather than knows, it will invent. Time to catch it doing so.' },
      { n: 6, name: 'Hallucination Lab', act: 'Query an LLM about local history and geography; fact-check against library, elders, archives; publish an \u201cerror report\u201d. The signature Road Crew safety lesson.', hook: 'Entirely \u27e8local\u27e9 \u2014 that\u2019s the point', actShort: 'Catch, verify and publish LLM errors',
        sign: 'octagon', glyph: 'FALSE', h: 'Make the machine show its seams', lt: 'HALLUCINATION LAB',
        p: ['The signature Road Crew lesson. Interrogate an LLM about YOUR town \u2014 founding dates, river lengths, old street names \u2014 then <strong>verify every claim</strong> against the library, the archives, the elders. The inventions you catch get written up.', 'Publish a proper <strong>error report</strong>: claim, source checked, verdict, correction. One document that proves, with receipts, why AI output is a claim \u2014 never a source.'],
        ex: { t: 'Error report format', i: ['g|CLAIM: quoted exactly as the LLM said it', 'g|CHECKED AGAINST: archive, book, or named elder', 'g|VERDICT: confirmed / false / unverifiable', 'g|CORRECTION: the real fact, with its source'] },
        co: ['Why local?', 'Global facts are well-patrolled; LOCAL facts are where LLMs invent freely \u2014 and where you hold the checking power.', true],
        quiz: { q: 'The LLM cites a \u201c1923 flood\u201d in your town. Library archives: nothing. Elders: nothing. Verdict?', o: ['A|Confirmed \u2014 the AI said it confidently', 'B|Unsupported \u2014 likely hallucination; record it with your checking trail|1', 'C|The archives must be wrong'], rf: 'Confidence is not evidence. Claim checked, sources silent, verdict recorded \u2014 that\u2019s the lab working.', wf: 'Confidence \u2260 evidence, and archives + elders outrank autocomplete. Verdict: <b>likely hallucination</b>, documented.' },
        sort: { name: 'SOURCE OR CLAIM?', prompt: 'Sort what you\u2019re holding:', g: 'A SOURCE \ud83d\udfe2', r: 'JUST A CLAIM \ud83d\udd34', intro: 'GREEN = can settle a fact. RED = needs checking first.', items: ['The town archive\u2019s flood records|green', 'An LLM\u2019s confident paragraph|red', 'An elder\u2019s first-hand account|green', 'A screenshot of a chatbot answer|red', 'The library\u2019s newspaper microfilm|green', '\u201cEveryone online says so\u201d|red'] },
        learned: 'The lab method: <b>claim \u2192 check \u2192 verdict \u2192 correction</b>, and the law it proves \u2014 AI output is a claim, never a source.', take: 'Your error report joins the class archive. From today, \u201cthe AI said so\u201d is banned as a reason.' },
      { n: 7, name: 'Prompting as Specification', act: 'Prompt-craft studio: iterate prompts for a defined task; compare outputs; document what changed and why.', hook: 'Tasks like \u27e8translate a notice, summarize a council report\u27e9', actShort: 'Iterate prompts; log every change',
        sign: 'rect', glyph: 'SPEC', h: 'A prompt is a spec, not a wish', lt: 'PROMPT STUDIO',
        p: ['\u201cSummarize this council report\u201d \u2192 mush. \u201cSummarize for busy parents: 5 bullets, plain words, decisions + dates only\u201d \u2192 useful. The difference is <strong>specification</strong>: audience, format, constraints, success criteria.', 'Studio discipline: iterate the prompt, compare outputs side by side, and keep a <strong>prompt log</strong> \u2014 what you changed, what improved, why. The log IS the learning; process is gold.'],
        ex: { t: 'Anatomy of a spec-grade prompt', i: ['g|PERSONA: who the AI should act as', 'g|REQUEST: the task, with a verb', 'g|OUTPUT: length, format, tone, language', 'g|CHECK: how you\u2019ll verify before using', 'b|\u201cMake it good\u201d \u2014 hope is not a spec'] },
        co: ['Transferable skill', 'Specifying clearly \u2014 audience, format, constraints \u2014 is the same skill as briefing a designer or writing requirements. Prompting is practice for engineering.'],
        build: 'Studio time. PERSONA: communications volunteer for the council. REQUEST: turn a long council report into a notice residents will actually read. OUTPUT: define exactly \u2014 length, reading level, language(s), what to include and omit. CHECK: your verification step before it goes on the noticeboard.',
        quiz: { q: 'Draft 3 of your prompt beats draft 1. What made the difference, most likely?', o: ['A|Typing more politely', 'B|Tighter specification \u2014 audience, format and constraints the model must hit|1', 'C|The AI warmed up'], rf: 'Models don\u2019t warm up \u2014 specs sharpen. Your log shows exactly which constraint did the work.', wf: 'No warm-ups, and politeness isn\u2019t the lever \u2014 <b>specification</b> is: audience, format, constraints. Check your log.' },
        learned: 'Prompting as <b>specification</b>: persona, request, output, check \u2014 iterated and logged like an engineer.', take: 'Keep the prompt log for every AI task this year. In audits (and jobs), \u201cshow your process\u201d wins.' },
      { n: 8, name: 'Integrity Charter Workshop', act: 'Draft the class AI-use policy for schoolwork; negotiate with teachers; sign.', hook: 'Aligned with \u27e8the school\u2019s / nation\u2019s assessment rules\u27e9', actShort: 'Negotiate and sign the class AI policy',
        sign: 'rect', glyph: '\u270d', h: 'Write the rules you\u2019ll be judged by', lt: 'INTEGRITY CHARTER',
        p: ['Instead of receiving AI rules, you <strong>write them</strong> \u2014 then negotiate with your teachers, line by line, until both sides sign. When is AI help legitimate (brainstorming? checking?) and when is it fraud (writing your assessed essay)?', 'The load-bearing word: <strong>disclosure</strong>. Work you\u2019re graded on shows what AI did and what you did. Undisclosed help isn\u2019t cleverness \u2014 it makes your grade a lie about your ability.'],
        ex: { t: 'Charter clauses that work', i: ['g|Brainstorming with AI: allowed, disclosed', 'g|Grammar checking your own draft: allowed', 'g|AI writes the assessed essay: banned \u2014 the grade must measure YOU', 'g|Every use logged in one disclosure line'] },
        co: ['Why disclosure?', 'A grade is information about what YOU can do. Hidden AI help corrupts that information \u2014 for teachers, parents, and future-you.', true],
        quiz: { q: 'AI drafted half your assessed essay; you edited heavily and submitted without mention. Charter verdict?', o: ['A|Fine \u2014 editing made it yours', 'B|Violation \u2014 assessed work misrepresented; disclosure was owed|1', 'C|Fine if the grade is good'], rf: 'Heavy editing doesn\u2019t undo the misrepresentation. The charter asks one thing: say what the AI did.', wf: 'Editing doesn\u2019t transfer authorship of the half AI wrote. Assessed work demands <b>disclosure</b> \u2014 that\u2019s the deal you signed.' },
        sort: { name: 'CHARTER CALLS', prompt: 'Sort the AI uses for assessed schoolwork:', g: 'LEGITIMATE + DISCLOSED \ud83d\udfe2', r: 'CHARTER VIOLATION \ud83d\udd34', intro: 'GREEN = help that leaves the grade honest. RED = the grade becomes a lie.', items: ['Brainstorm 5 essay angles, noted in disclosure|green', 'AI writes the conclusion, undisclosed|red', 'Explain a concept you then write up yourself|green', 'Paraphrasing tool to dodge plagiarism checks|red', 'Practice quiz questions before the test|green', 'AI solves the take-home exam|red'] },
        learned: 'Negotiated AI ethics: legitimate help vs. fraud, with <b>disclosure</b> as the dividing line \u2014 and your own signature on it.', take: 'Semester 2 next: Bias, Power & Truth. You have the technical grounding \u2014 now comes the critical core.' },
    ] },
    { name: 'Bias, Power & Truth', mods: [
      { n: 9, name: 'The Bias Hunt', act: 'Audit an image generator or classifier for how it represents your people, dress, streets, and professions.', hook: '\u201cGenerate \u27e8a doctor / a farmer / a wedding here\u27e9\u201d \u2014 analyze the results', actShort: 'Audit a generator\u2019s picture of YOUR people',
        sign: 'octagon', glyph: 'BIAS', h: 'Who does the machine think you are?', lt: 'THE BIAS HUNT',
        p: ['Prompt an image generator: \u201ca doctor\u201d, \u201ca farmer\u201d, \u201ca wedding in your town\u201d. Now audit the output like a scientist: who appears? What dress, skin, streets? Does it look like <strong>your</strong> people \u2014 or like a stock-photo stereotype from somewhere else?', 'Method over outrage: <strong>fixed prompts \u2192 many samples \u2192 tally what appears \u2192 compare with reality</strong> (heritage-centre photos, your own streets). The gap, counted, is bias made measurable.'],
        ex: { t: 'Audit protocol', i: ['g|Same prompt, 20 samples \u2014 one is an anecdote', 'g|Tally: gender, dress, setting, skin tone', 'g|Baseline: real photos of real local doctors/farmers/weddings', 'b|One shocking image, screenshotted \u2014 that\u2019s a tweet, not an audit'] },
        co: ['Where bias comes from', 'The generator learned from internet images \u2014 in which some people are everywhere and your town barely exists. Bias in the data becomes bias in the dream.', true],
        quiz: { q: '20/20 \u201cdoctor\u201d generations show the same gender and none in local dress. What have you established?', o: ['A|Doctors look like that', 'B|A measurable representation bias, traceable to skewed training data|1', 'C|Nothing \u2014 images are just images'], rf: 'Counted, repeatable, baselined \u2014 that\u2019s evidence. Thursday: compare against the heritage-centre photos.', wf: 'Images shape assumptions \u2014 and 20/20 is a <b>measured skew</b>, not a coincidence. That\u2019s auditable bias.' },
        sort: { name: 'AUDIT OR ANECDOTE?', prompt: 'Sort the bias-hunt moves:', g: 'AUDIT-GRADE \ud83d\udfe2', r: 'ANECDOTE-GRADE \ud83d\udd34', intro: 'GREEN = would survive a skeptic. RED = wouldn\u2019t.', items: ['20 samples per fixed prompt, tallied|green', 'One weird image, shared fast|red', 'Comparing output against real local photos|green', 'Cherry-picking the worst result|red', 'Publishing your method with your findings|green', '\u201cIt felt biased to me\u201d|red'] },
        learned: 'Bias auditing as method: <b>fixed prompts, many samples, tallies, real baselines</b> \u2014 turning \u201cit feels off\u201d into evidence.', take: 'Bring your tallies Thursday \u2014 we compare against the heritage-centre photos, and the evidence goes in your portfolio.' },
      { n: 10, name: 'Whose Data? Whose Language?', act: 'Investigate how well AI serves the local language(s); measure translation quality on 20 sentences with bilingual elders.', hook: 'The \u27e8local / minority language\u27e9 gap becomes measurable evidence', actShort: 'Measure the language gap with elders',
        sign: 'triangle', glyph: 'GAP', h: 'The language gap, measured', lt: 'WHOSE LANGUAGE?',
        p: ['Take 20 sentences \u2014 greetings, proverbs, market talk, official notices \u2014 and run them through machine translation. Then sit with <strong>bilingual elders</strong> and score each: accurate / mangled / nonsense. You\u2019re producing data nobody else has.', 'The pattern you\u2019ll find: plain sentences fare okay; culture-rich ones collapse. Behind it, economics \u2014 models serve languages with data, and data follows money and power. Your scores make that <strong>gap visible</strong>.'],
        ex: { t: 'Scoring protocol', i: ['g|20 sentences, mixed: plain, official, proverbial', 'g|Elders score meaning, not just words', 'g|Note WHERE it fails: idiom? grammar? vocabulary?', 'g|Result: a defensible gap measurement'] },
        co: ['Elders as experts', 'In this module the elders are the measurement instrument \u2014 credit them as co-researchers, by name (with their permission).'],
        build: 'Design the study. PERSONA: lead researcher of the language-gap study. REQUEST: pick your 20 sentences \u2014 justify the mix (plain / official / proverbial). OUTPUT: scoring sheet with your 3-level scale, defined precisely enough that two elders score alike. CHECK: how you\u2019ll handle disagreement between elders.',
        quiz: { q: 'Machine translation nails \u201cWhere is the clinic?\u201d but destroys the harvest proverb. The structural reason?', o: ['A|Proverbs are untranslatable by anyone', 'B|Training data: plain phrases are abundant online; your culture-rich text barely exists there|1', 'C|The AI needs a newer version'], rf: 'Bilingual elders translate that proverb fine \u2014 the machine lacks the DATA. Which is a choice someone made.', wf: 'Elders translate it fine! The failure is <b>data scarcity</b> \u2014 culture-rich local text barely exists in training sets.' },
        learned: 'How to <b>measure</b> a language gap \u2014 sentence sets, elder scoring, failure typing \u2014 and the data economics behind it.', take: 'Your scores are evidence for the Mock Council (M16): should public services rely on machine translation here?' },
      { n: 11, name: 'Deepfakes & Synthetic Media', act: 'Detection workshop; ethics of synthetic voices and faces; local media-law snapshot.', hook: 'Analyze a teacher-curated \u27e8local misinformation case\u27e9', actShort: 'Detect synthetic media; know the law',
        sign: 'octagon', glyph: 'FAKE', h: 'Seeing is no longer believing', lt: 'DEEPFAKES',
        p: ['Faces swapped, voices cloned from seconds of audio, events synthesized. Detection workshop: study a teacher-curated <strong>local misinformation case</strong> \u2014 artifacts (boundary blur, lighting mismatch, odd blinks), but above all <strong>provenance</strong>: where did this come from, who first posted, does any original exist?', 'Ethics + law: cloning a classmate\u2019s voice is harassment, not comedy. Your region\u2019s media-law snapshot says what\u2019s illegal \u2014 your ethics cover what\u2019s merely disgraceful.'],
        ex: { t: 'Verification stack', i: ['g|Provenance first: source, date, original?', 'g|Cross-check: does any other source confirm the event?', 'g|Artifacts last: blur, lighting, lip-sync (weakest \u2014 fakes improve)', 'b|\u201cLooks real to me\u201d \u2014 that\u2019s what it\u2019s FOR'] },
        co: ['The liar\u2019s dividend', 'Deepfakes cut both ways: fakes get believed, AND real footage gets dismissed as \u201cprobably AI\u201d. Verification skills defend both truths.', true],
        quiz: { q: 'A voice clip of a local official \u201cconfessing\u201d spreads on chat groups. Your first move?', o: ['A|Forward it \u2014 people deserve to know', 'B|Provenance check: original source, first post, independent confirmation \u2014 before any sharing|1', 'C|It sounds like him, so it\u2019s real'], rf: 'Sounding like him is exactly what voice cloning does. Provenance before amplification \u2014 always.', wf: '\u201cSounds like him\u201d is the attack, not the proof. <b>Provenance first</b>; forwarding unverified audio makes you the vector.' },
        sort: { name: 'STRONG OR WEAK EVIDENCE?', prompt: 'Sort the verification signals:', g: 'STRONG SIGNAL \ud83d\udfe2', r: 'WEAK SIGNAL \ud83d\udd34', intro: 'GREEN = hard to fake. RED = easy to fake or feel.', items: ['Original file with intact source history|green', '\u201cIt looks totally real\u201d|red', 'Two independent outlets confirm the event|green', 'Millions of views|red', 'The person filmed confirms it happened|green', 'A dramatic caption in all caps|red'] },
        learned: 'Synthetic media literacy: <b>provenance \u2192 cross-check \u2192 artifacts</b>, the liar\u2019s dividend, and where local law draws lines.', take: 'House rule for every dramatic clip: verify before you amplify. Teach the provenance check at home.' },
      { n: 12, name: 'Recommender Systems & Attention', act: 'Simulate a feed algorithm with cards; compute engagement vs. wellbeing trade-offs.', hook: 'What goes viral \u27e8here\u27e9, and why', actShort: 'Be the algorithm; feel the trade-off',
        sign: 'triangle', glyph: 'FEED', h: 'The feed has a goal. It isn\u2019t yours.', lt: 'RECOMMENDERS',
        p: ['Card game: you ARE the algorithm. Each round, choose which post to show next, scoring points for <strong>engagement</strong> \u2014 clicks, watch-time, shares. Within minutes you\u2019ll discover what every platform discovered: outrage and envy score. Calm truth doesn\u2019t.', 'Then recompute the same choices scoring <strong>wellbeing</strong> instead \u2014 and watch your feed transform. Recommenders aren\u2019t evil; they\u2019re <strong>obedient</strong>. They maximize exactly what they\u2019re told to.'],
        ex: { t: 'What the simulation teaches', i: ['g|Engagement-scored feeds drift toward outrage', 'g|The algorithm optimizes ITS metric, not your good', 'g|Same system, wellbeing metric \u2192 different feed', 'b|\u201cI\u2019m immune to my feed\u201d \u2014 the metric says otherwise'] },
        co: ['The question that matters', 'For any feed, ask: \u201cwhat number is this optimizing?\u201d Follow that number and the feed\u2019s behaviour \u2014 and yours \u2014 makes sudden sense.'],
        quiz: { q: 'Your simulated feed keeps surfacing the angriest posts. Nobody coded \u201cshow anger\u201d. Why does it happen?', o: ['A|The algorithm developed feelings', 'B|Anger maximizes the engagement metric, so an engagement-optimizer converges on it|1', 'C|Random chance'], rf: 'Emergent, not intended \u2014 the metric did it. Which means changing the metric changes the feed.', wf: 'No feelings, no chance \u2014 the <b>metric</b> did it. Optimize engagement, get outrage; the fix is the metric.' },
        sort: { name: 'METRIC DETECTIVE', prompt: 'Sort the feed behaviours by the metric behind them:', g: 'ENGAGEMENT-DRIVEN \ud83d\udfe2', r: 'WELLBEING-DRIVEN \ud83d\udd34', intro: 'GREEN = maximizing clicks/time. RED = optimizing for the user\u2019s good.', items: ['Autoplay the next, more extreme video|green', 'A \u201cyou\u2019ve scrolled a lot \u2014 break?\u201d nudge|red', 'Rage-bait ranked to the top|green', 'Chronological feed from people you chose|red', 'Infinite scroll, no stopping point|green', 'Daily time limit you set, enforced|red'] },
        learned: 'Recommenders <b>obediently maximize their metric</b> \u2014 engagement breeds outrage; different metrics build different feeds.', take: 'Audit one of your own feeds this week: what\u2019s it optimizing? Where has it been steering you?' },
      { n: 13, name: 'Privacy Engineering', act: 'Threat-model a school app; learn anonymization, consent, and data minimization by fixing a leaky (mock) dataset.', hook: 'Mock data mirrors \u27e8local formats \u2014 names, IDs, addresses\u27e9', actShort: 'Fix a leaky dataset; think like an attacker',
        sign: 'octagon', glyph: 'LEAK', h: 'Privacy is engineered, not promised', lt: 'PRIVACY ENGINEERING',
        p: ['A mock school-app dataset lands on your desk \u2014 names, IDs, addresses in local formats \u2014 <strong>leaky everywhere</strong>. Your job: think like an attacker (who could learn what?), then fix it: <strong>minimize</strong> (collect less), <strong>anonymize</strong> (strip identifiers), <strong>aggregate</strong> (report groups, not people).', 'The famous trap: \u201canonymized\u201d data that re-identifies \u2014 birthday + neighbourhood + school year can pinpoint one student. Real anonymization survives an adversary, not just a glance.'],
        ex: { t: 'The engineer\u2019s toolkit', i: ['g|Threat model: who wants this data, for what?', 'g|Minimize: don\u2019t collect what you don\u2019t need', 'g|Aggregate: \u201c40% of students\u201d beats a list of names', 'b|\u201cWe removed names, it\u2019s anonymous\u201d \u2014 birthday+area often re-identifies'] },
        co: ['Consent means informed', 'A checkbox nobody reads is not consent. If users can\u2019t say what they agreed to, the design failed \u2014 legally AND morally.', true],
        quiz: { q: 'The \u201canonymized\u201d dataset keeps birth date, neighbourhood and school year. Safe to publish?', o: ['A|Yes \u2014 names are gone', 'B|No \u2014 those three together can re-identify individuals; aggregate or generalize first|1', 'C|Safe if the file is renamed'], rf: 'Quasi-identifiers are the classic leak. Bucket the birth years, coarsen the areas \u2014 then reconsider.', wf: 'Names gone \u2260 anonymous. Birthday + area + year is a <b>fingerprint</b> \u2014 the classic re-identification attack.' },
        sort: { name: 'LEAK OR SAFE?', prompt: 'Sort the data-handling choices for the school app:', g: 'ENGINEERED SAFE \ud83d\udfe2', r: 'LEAK WAITING \ud83d\udd34', intro: 'GREEN = survives an attacker. RED = breach material.', items: ['Publish class averages only|green', 'Full names in a shared spreadsheet|red', 'IDs replaced with random codes, key stored separately|green', '\u201cAnonymous\u201d rows with birthday + address|red', 'Collecting only what the feature needs|green', 'Keeping everything forever, just in case|red'] },
        learned: 'Privacy engineering: <b>threat-model, minimize, anonymize properly, aggregate</b> \u2014 and why quasi-identifiers betray \u201canonymous\u201d data.', take: 'These exact skills gate your capstone: no data collection before your Data Ethics Gate (M19) passes.' },
      { n: 14, name: 'AI, Work & Our Economy', act: 'Sector study: how AI is entering the region\u2019s top three industries; interview workers.', hook: '\u27e8Port, farm, factory, tourism, tech park\u27e9 \u2014 region-specific', actShort: 'Study AI in your region\u2019s top industries',
        sign: 'rect', glyph: 'WORK', h: 'Follow the tasks, not the headlines', lt: 'AI & THE ECONOMY',
        p: ['Skip the \u201crobots take all jobs\u201d headlines. Economists study <strong>tasks</strong>: every job is a bundle, and AI automates some tasks (logging, sorting, predicting) while others resist (judgement, dexterity, trust, care). Jobs <strong>reshape</strong> more than they vanish.', 'Field method: pick your region\u2019s top three sectors, interview real workers \u2014 which tasks are already assisted? Which would they gladly hand over? Who gains, who pays, who decides?'],
        ex: { t: 'Task-lens questions', i: ['g|Which tasks repeat and follow patterns? (automatable)', 'g|Which need trust, touch, judgement? (resistant)', 'g|Who captures the gains \u2014 worker, owner, platform?', 'b|\u201cWill AI take the job?\u201d \u2014 wrong unit; ask about tasks'] },
        co: ['Power, again', 'Whether AI helps a worker or squeezes them is rarely decided by the tech \u2014 it\u2019s decided by who deploys it, and on what terms. That\u2019s policy, not fate.'],
        build: 'Prepare the sector study. PERSONA: junior researcher for a regional labour report. REQUEST: pick one top-three sector and draft interview questions using the task lens. OUTPUT: 5 questions \u2014 tasks assisted, tasks resistant, and who benefits. CHECK: how you\u2019ll avoid leading questions and protect interviewees\u2019 privacy.',
        quiz: { q: 'The port automated container tracking; the crane crews now handle MORE exceptions and safety calls. What happened?', o: ['A|The workers are being phased out', 'B|Task reshaping: routine tracking automated, human work shifted toward judgement and exceptions|1', 'C|Nothing changed'], rf: 'That\u2019s the classic pattern \u2014 routine tasks go, judgement tasks concentrate. The question left: are they paid for the upgrade?', wf: 'Look at the <b>tasks</b>: routine tracking went to machines; judgement and exceptions grew. Reshaping, not (yet) replacement.' },
        learned: 'The <b>task lens</b>: AI automates task-by-task, jobs reshape, and who benefits is a power question \u2014 answerable by fieldwork.', take: 'Your sector findings feed the Mock Council (M16) \u2014 someone will have to speak for the workers.' },
      { n: 15, name: 'Environment & Compute', act: 'Estimate the energy and water footprint of AI vs. local resource realities; debate.', hook: '\u27e8Water-stressed regions\u27e9 foreground water; others energy / e-waste', actShort: 'Estimate AI\u2019s footprint; debate the trade',
        sign: 'triangle', glyph: 'H2O', h: 'The cloud drinks and burns', lt: 'ENVIRONMENT & COMPUTE',
        p: ['\u201cThe cloud\u201d is buildings full of hot chips \u2014 training a large model can consume the electricity of thousands of homes, and data centres drink <strong>water</strong> for cooling. Where water is scarce, that\u2019s not an abstraction; it\u2019s your river.', 'Estimation over slogans: rough-number AI\u2019s footprint against local realities (a borehole\u2019s daily yield, a village\u2019s power use), then <strong>debate</strong> \u2014 which AI uses justify the cost here, and which don\u2019t? Reasonable people will disagree; numbers keep the disagreement honest.'],
        ex: { t: 'Footprint estimation kit', i: ['g|Training vs. using: training is the giant one-off, queries add up at scale', 'g|Compare to local units: homes powered, boreholes drained', 'g|E-waste: yesterday\u2019s chips pile up somewhere \u2014 often HERE', 'b|\u201cThe cloud is weightless\u201d \u2014 it\u2019s concrete, copper and cooling towers'] },
        co: ['Debate rule', 'Attack estimates with better estimates, not louder feelings. \u201cYour number is off because\u2026\u201d is Road Crew for \u201cI disagree\u201d.'],
        quiz: { q: 'A data centre is proposed upstream of a water-stressed town. What\u2019s the Road Crew move?', o: ['A|Oppose all technology', 'B|Demand the numbers \u2014 water draw vs. local supply \u2014 and weigh benefits against costs openly|1', 'C|Welcome it unconditionally \u2014 progress is progress'], rf: 'Neither -phobia nor -mania: estimates on the table, trade-offs debated in daylight. That\u2019s citizenship.', wf: 'Both extremes skip the homework. Get the <b>water numbers</b>, compare with local supply, debate the trade openly.' },
        sort: { name: 'FOOTPRINT FACT-CHECK', prompt: 'Sort the claims:', g: 'DEFENSIBLE \ud83d\udfe2', r: 'HAND-WAVING \ud83d\udd34', intro: 'GREEN = estimable, checkable. RED = slogan in a lab coat.', items: ['\u201cTraining ran on N chips for M weeks \u2014 here\u2019s the energy math\u201d|green', '\u201cAI is basically free to run\u201d|red', '\u201cCooling uses litres per query \u2014 scaled, that\u2019s our borehole\u201d|green', '\u201cThe cloud has no location\u201d|red', '\u201cOld GPUs become e-waste; here\u2019s where ours goes\u201d|green', '\u201cGreen tech, trust us\u201d|red'] },
        learned: 'AI\u2019s physical bill \u2014 <b>energy, water, e-waste</b> \u2014 estimated in local units and debated with numbers, not slogans.', take: 'Bring your footprint estimates to the Mock Council next module. Somebody will play the data-centre lobbyist.' },
      { n: 16, name: 'Mock Council: Regulate It', act: 'Role-play: draft one AI rule for your city; defend it before a panel.', hook: 'Use the actual \u27e8council / panchayat / municipality\u27e9 structure', actShort: 'Draft one AI rule; survive the panel',
        sign: 'rect', glyph: 'LAW', h: 'Write a rule that survives contact', lt: 'MOCK COUNCIL',
        p: ['Semester finale: the class becomes your city\u2019s actual governing body \u2014 council, panchayat, municipality \u2014 with real roles: proposers, opposition, affected residents, a lobbyist or two. Each team drafts <strong>one enforceable AI rule</strong> for the city and defends it.', 'Everything you\u2019ve gathered is ammunition: bias tallies (M9), language scores (M10), deepfake cases (M11), feed metrics (M12), privacy leaks (M13), worker interviews (M14), footprint estimates (M15). Good rules cite <strong>evidence</strong>; great rules say who enforces, how, and what it costs.'],
        ex: { t: 'Anatomy of an enforceable rule', i: ['g|SCOPE: exactly who and what it covers', 'g|REQUIREMENT: what must (not) be done', 'g|ENFORCEMENT: who checks, what penalty', 'g|EVIDENCE: your semester\u2019s data, cited', 'b|\u201cAI must be good and fair\u201d \u2014 unenforceable poetry'] },
        co: ['Steelman rule', 'Before the panel, argue the OTHER side\u2019s best case out loud. Rules that survive steelmanning survive councils.'],
        build: 'Draft your rule. PERSONA: council member proposing an AI ordinance. REQUEST: one enforceable rule (e.g. disclosure of synthetic media in local campaigns; language-access standards for public AI services). OUTPUT: scope + requirement + enforcement + the evidence you\u2019ll cite. CHECK: the strongest objection you expect, and your prepared answer.',
        quiz: { q: 'Two drafts: (a) \u201cAI shall be used ethically\u201d, (b) \u201cPublic offices using automated translation must publish elder-verified accuracy scores yearly\u201d. Which survives the panel?', o: ['A|(a) \u2014 it covers everything', 'B|(b) \u2014 scoped, checkable, enforceable, and backed by your M10 evidence|1', 'C|Both equally'], rf: 'Covering everything enforces nothing. Scope + measurement + enforcement = a rule with teeth.', wf: '\u201cCovers everything\u201d = enforces nothing. (b) is <b>scoped and checkable</b> \u2014 and your M10 scores back it.' },
        learned: 'Governance as craft: <b>scope, requirement, enforcement, evidence</b> \u2014 and defending a rule against its best opposition.', take: 'Semester 3 turns outward: a real client, real data ethics, a real build. The critical core goes to work.' },
    ] },
    { name: 'Build for Someone', mods: [
      { n: '17\u201318', name: 'Client Discovery', act: 'Partner with a real local client \u2014 shop, clinic outreach, farm co-op, library, NGO \u2014 and define a problem AI might help with. Or conclude honestly that it shouldn\u2019t.', hook: 'Clients from the \u27e8Partner Roster\u27e9', actShort: 'Find the real problem behind the ask',
        sign: 'rect', glyph: 'ASK', h: 'The client\u2019s words are the start, not the spec', lt: 'CLIENT DISCOVERY',
        p: ['You now have a <strong>real client</strong> from the Partner Roster \u2014 a shop, clinic outreach team, farm co-op, library or NGO. Discovery means listening past the first ask: \u201cwe want an app\u201d usually hides \u201cwe lose track of orders\u201d. Interview, observe a real workday, write the problem in THEIR words, and get them to confirm it.', 'And hold the honest exit: some problems need a noticeboard, a phone rota, or a better form \u2014 <strong>not AI</strong>. Concluding \u201cno AI needed\u201d with reasons is a passing grade, and clients respect it.'],
        ex: { t: 'Discovery craft', i: ['g|Shadow a real shift before proposing anything', 'g|Ask for last month\u2019s ACTUAL pain, not hypotheticals', 'g|Restate the problem in their words; get a nod', 'b|Pitching your cool tech in meeting one \u2014 discovery inverted'] },
        co: ['Scope is a promise', 'Whatever problem you confirm here is what M26\u2019s Mid-Showcase judges you on. Write it down; sign it \u2014 both sides.'],
        build: 'Plan discovery. PERSONA: consulting team lead meeting the client. REQUEST: draft your interview + observation plan for the first visit. OUTPUT: 5 open questions, what you\u2019ll observe during a shift, and your problem-statement template. CHECK: how you\u2019ll confirm the problem is real \u2014 evidence from their records, not just opinions.',
        quiz: { q: 'The co-op says \u201cbuild us an AI chatbot\u201d. Observation shows members mainly miss the weekly price list. Best move?', o: ['A|Build the chatbot \u2014 the client is always right', 'B|Bring evidence back: the confirmed problem is price-list delivery \u2014 maybe SMS, maybe nothing AI at all|1', 'C|Build both'], rf: 'Discovery means solving the confirmed problem, not the first ask. Clients thank you later \u2014 usually.', wf: 'The client owns the <b>problem</b>; you owe them the right <b>solution</b>. Evidence says price-list delivery \u2014 start there.' },
        learned: 'Discovery: <b>listen, observe, restate, confirm</b> \u2014 and the professional courage to say \u201cthis doesn\u2019t need AI\u201d.', take: 'Problem confirmed and signed? Nothing else proceeds \u2014 the Data Ethics Gate is next, and it\u2019s strict.' },
      { n: '19\u201320', name: 'Data Ethics Gate', act: 'Consent forms, data-minimization plan, and community-review sign-off before any data is gathered.', hook: 'Rules from the \u27e8Values & Ethics Charter\u27e9', actShort: 'Pass the gate before touching any data',
        sign: 'octagon', glyph: 'GATE', h: 'No sign-off, no data. No exceptions.', lt: 'DATA ETHICS GATE',
        p: ['Before your project touches a single record, three documents must pass: a <strong>consent form</strong> humans actually understand (what\u2019s collected, why, until when, how to withdraw), a <strong>data-minimization plan</strong> (every field justified or cut \u2014 your M13 skills), and <strong>community-review sign-off</strong> under the Values & Ethics Charter.', 'This mirrors how real research works \u2014 ethics boards gate studies for good reason. The gate isn\u2019t bureaucracy slowing you down; it\u2019s the project\u2019s <strong>licence to be trusted</strong>.'],
        ex: { t: 'Gate checklist', i: ['g|Consent in plain local language, withdrawal path included', 'g|Every data field: needed? Then justify. Not? Then cut', 'g|Storage: where, encrypted how, deleted when', 'b|\u201cWe\u2019ll sort consent later\u201d \u2014 later is a breach with a date'] },
        co: ['Withdrawal is sacred', 'Consent you can\u2019t take back isn\u2019t consent. Your form must make leaving as easy as joining.', true],
        quiz: { q: 'Deadline pressure: a teammate suggests collecting the co-op\u2019s member data now, \u201cconsent forms next week\u201d. Gate says?', o: ['A|Fine \u2014 a week hardly matters', 'B|Absolute no \u2014 data before consent poisons the whole project\u2019s legitimacy|1', 'C|Fine if the data seems harmless'], rf: 'The gate exists precisely for deadline pressure. Unconsented collection can\u2019t be consented retroactively.', wf: 'A week matters completely \u2014 consent can\u2019t be granted <b>backwards</b>. No sign-off, no data. That\u2019s the gate.' },
        sort: { name: 'GATE-READY?', prompt: 'Sort the project practices:', g: 'PASSES THE GATE \ud83d\udfe2', r: 'GATE VIOLATION \ud83d\udd34', intro: 'GREEN = consent + minimization done right. RED = would fail review.', items: ['Plain-language consent, read aloud for anyone who prefers|green', 'A jargon consent wall nobody reads|red', 'Collecting order counts, not customer names|green', '\u201cExtra fields, might be useful later\u201d|red', 'A named person who deletes data on request|green', 'Data on a teammate\u2019s personal phone|red'] },
        learned: 'The gate discipline: <b>informed consent, minimization, community sign-off</b> \u2014 before any collection, under any deadline.', take: 'Gate passed? Then \u2014 and only then \u2014 the Build Sprint begins. Bring the signed plan; it constrains the build.' },
      { n: '21\u201323', name: 'Build Sprint', act: 'Options ladder by resources: no-code ML tools \u00b7 block/Python + pre-trained models \u00b7 LLM workflow with human-in-the-loop \u00b7 fully unplugged decision-support system. All valid.', hook: 'Rung chosen by the \u27e8Infrastructure Reality Check\u27e9', actShort: 'Three weeks: build on your rung',
        sign: 'circle', glyph: 'BUILD', h: 'Pick your rung, keep a human in the loop', lt: 'BUILD SPRINT',
        p: ['Three build weeks. The Infrastructure Reality Check picks your rung on the <strong>options ladder</strong>: no-code ML \u00b7 blocks/Python with pre-trained models \u00b7 an LLM workflow with human review \u00b7 or a fully unplugged decision-support system (paper flowcharts count \u2014 they run on any infrastructure, forever). <strong>Every rung is a real build.</strong>', 'Sprint discipline: demo to the client <strong>weekly</strong>, log every surprise, and wherever AI output touches a real decision, design the <strong>human-in-the-loop</strong> \u2014 who reviews, who can override, who answers for it.'],
        ex: { t: 'Sprint rules', i: ['g|Weekly client demo \u2014 ugly and real beats polished and late', 'g|Human-in-the-loop drawn INTO the design, with a name', 'g|Change log: what you altered after each demo and why', 'b|Rung-shame (\u201cpaper isn\u2019t real tech\u201d) \u2014 the co-op disagrees'] },
        co: ['Loop rule', 'Wherever the system\u2019s output meets a real person\u2019s life \u2014 a price, a schedule, a diagnosis hint \u2014 a HUMAN reviews before it lands. Design the loop, name the human.', true],
        build: 'Sprint plan. PERSONA: tech lead on your rung of the ladder. REQUEST: plan week one \u2014 the smallest end-to-end slice your client can touch. OUTPUT: the slice, each teammate\u2019s task, and the human-in-the-loop for every AI-touched decision. CHECK: your weekly demo ritual \u2014 when, where, and what \u201cworking\u201d means for the client.',
        quiz: { q: 'No school devices this term, so the team ships a paper decision-flowchart the co-op uses daily. A classmate calls it \u201cnot a real AI project\u201d. Verdict?', o: ['A|Correct \u2014 no computer, no project', 'B|Wrong \u2014 it\u2019s a decision-support system serving a real client; the ladder exists exactly for this|1', 'C|Only real if rebuilt digitally later'], rf: 'Serving the client on available infrastructure IS the engineering. The ladder has no shameful rungs.', wf: 'The measure is <b>client value on real infrastructure</b> \u2014 not silicon. The unplugged rung is a designed, tested system.' },
        learned: 'Sprint craft: the <b>options ladder</b>, weekly client demos, change logs \u2014 and a named human in every consequential loop.', take: 'Next: Red-Team Day. Another team attacks your build \u2014 bias, privacy, failure, misuse. Patch your obvious holes now.' },
      { n: 24, name: 'Red-Team Day', act: 'Teams attack each other\u2019s projects: bias, privacy, failure, misuse.', hook: 'Attack scenarios from \u27e8local contexts\u27e9', actShort: 'Attack their build; welcome attacks on yours',
        sign: 'octagon', glyph: 'ATK', h: 'Better your classmates than the real world', lt: 'RED-TEAM DAY',
        p: ['Today teams swap projects and <strong>attack</strong> along four lanes: <strong>bias</strong> (who does it fail?), <strong>privacy</strong> (what leaks?), <strong>failure</strong> (what breaks it \u2014 power cut, wrong input, absent volunteer?), <strong>misuse</strong> (how would a bad actor bend it?). Scenarios come from real local contexts.', 'Defenders: your score isn\u2019t \u201cfewest findings\u201d \u2014 it\u2019s <strong>response quality</strong>. Log every finding, thank the attacker, triage: fix now / mitigate / accept with reasons. That log is showcase gold.'],
        ex: { t: 'The four attack lanes', i: ['g|BIAS: run it for the users least like its builders', 'g|PRIVACY: what can I learn that I shouldn\u2019t?', 'g|FAILURE: unplug things; feed it garbage; remove a person', 'g|MISUSE: think like the town\u2019s worst actor, on paper'] },
        co: ['Red-team honour', 'Attack systems, never people. Write findings so the builders can fix them \u2014 you\u2019re the fire drill, not the fire.'],
        quiz: { q: 'The red team finds your price-helper fails for members who can\u2019t read. Best response?', o: ['A|\u201cOut of scope \u2014 most members read\u201d', 'B|Log it, thank them, triage it \u2014 likely a voice/pictogram path or a human fallback|1', 'C|Argue the finding is unfair'], rf: 'That finding is a real member you\u2019d have failed. Triage with reasons \u2014 that\u2019s mature engineering.', wf: '\u201cMost members\u201d is how bias ships. <b>Log \u2192 thank \u2192 triage</b>; non-readers get a path or a person.' },
        sort: { name: 'FINDING TRIAGE', prompt: 'Red-team findings on a clinic-queue helper \u2014 triage:', g: 'FIX BEFORE LAUNCH \ud83d\udfe2', r: 'MITIGATE / ACCEPT WITH REASONS \ud83d\udd34', intro: 'GREEN = blocking issue. RED = manage it, document it.', items: ['Patient names visible on the public screen|green', 'Fails during a total power cut|red', 'Predicts badly for the rare night shift|red', 'No consent notice at the queue kiosk|green', 'Volunteer could read the raw logs|green', 'Slightly off during festival weeks|red'] },
        learned: 'Red-teaming\u2019s four lanes \u2014 <b>bias, privacy, failure, misuse</b> \u2014 and graceful defence: log, thank, triage.', take: 'Fold the fixes in this week. M25 turns your triage log into honest documentation \u2014 the model card.' },
      { n: 25, name: 'Iterate & Document', act: 'Model cards / project cards: intended use, limits, data provenance, known failure modes.', hook: 'Written for \u27e8your client\u27e9, in plain language', actShort: 'Write the honest model card',
        sign: 'rect', glyph: 'CARD', h: 'Honest limits are a feature', lt: 'MODEL CARD',
        p: ['Real AI labs ship <strong>model cards</strong> \u2014 honest one-pagers stating what a system is for, what it was built from, and where it fails. Yours goes further: written in <strong>plain language for your client</strong>, in the languages they read.', 'Four sections: <strong>intended use</strong> (and explicit non-uses), <strong>data provenance</strong> (what data, whose consent \u2014 your gate documents), <strong>known failure modes</strong> (straight from Red-Team Day), and <strong>the loop</strong> (who reviews, who to call, how to complain). Documentation isn\u2019t the boring bit \u2014 it\u2019s the trust bit.'],
        ex: { t: 'Card sections', i: ['g|INTENDED USE: what it\u2019s for \u2014 and NOT for', 'g|DATA: sources, consent, deletion dates', 'g|KNOWN LIMITS: real failure modes, plainly stated', 'g|THE LOOP: reviewer, contact, complaint path', 'b|Marketing gloss (\u201c99% accurate!\u201d) \u2014 cards are for truth'] },
        co: ['The plain-language test', 'Read the card aloud to your client. Every sentence they don\u2019t understand is a sentence you rewrite \u2014 not one they should \u201cstudy\u201d.'],
        build: 'Draft the card. PERSONA: documentation lead. REQUEST: write the \u201cKnown limits\u201d and \u201cIntended use\u201d sections for your build. OUTPUT: plain-language bullets \u2014 including the three worst red-team findings and what you did about each. CHECK: the read-aloud test with a non-technical reader before it ships.',
        quiz: { q: 'A teammate wants to cut \u201cKnown limits\u201d \u2014 \u201cit makes us look bad\u201d. What\u2019s the truth?', o: ['A|Right \u2014 hide the flaws', 'B|Backwards \u2014 stated limits are what let the client trust and safely use the system|1', 'C|Limits sections are legally forbidden'], rf: 'A tool that admits its edges gets used correctly. Hidden flaws surface anyway \u2014 as betrayals.', wf: 'Hiding flaws doesn\u2019t remove them \u2014 it removes <b>trust</b> when they surface. Stated limits enable safe use.' },
        learned: 'The model card: <b>intended use, provenance, known limits, the loop</b> \u2014 honesty as an engineering deliverable.', take: 'Card + build + change log = your Mid-Showcase package. The client scores you next module.' },
      { n: 26, name: 'Mid-Showcase', act: 'Client scores usefulness, safety, and respect for community norms.', hook: 'Scored against \u27e8community norms\u27e9', actShort: 'The client grades your build',
        sign: 'circle', glyph: '\ud83c\udfc1', h: 'The only grade that counts wears no uniform', lt: 'MID-SHOWCASE',
        p: ['Today the <strong>client</strong> grades you \u2014 on three axes: <strong>usefulness</strong> (does it solve the confirmed problem from M17\u201318?), <strong>safety</strong> (gate documents, red-team fixes, the loop), and <strong>respect for community norms</strong> (language, customs, who it includes).', 'Run it like a real acceptance review: demo the end-to-end slice, walk the model card, show the change log, then <strong>listen</strong>. Scores below \u201chappy\u201d aren\u2019t failure \u2014 they\u2019re your Semester-4 backlog, priced by the person who matters.'],
        ex: { t: 'Acceptance review script', i: ['g|Demo the problem being solved \u2014 not features', 'g|Walk the card: limits stated before the client finds them', 'g|Show one red-team finding and its fix \u2014 builds instant trust', 'b|Talking over the client\u2019s criticism \u2014 the review IS the listening'] },
        co: ['Norms outrank cleverness', 'A technically brilliant build that ignores how things are done here scores zero on axis three. The community wrote the rubric; honour it.'],
        quiz: { q: 'The client scores usefulness 5/5 but norms 2/5: \u201cit only speaks the school language, and elders won\u2019t touch it\u201d. What did you just receive?', o: ['A|An unfair score \u2014 the tech works', 'B|Your Semester-4 priority list, from the only judge that counts|1', 'C|Proof elders dislike technology'], rf: 'Axis three is real: language access and elder inclusion go top of the capstone backlog.', wf: '\u201cWorks\u201d isn\u2019t \u201cworks for everyone here\u201d. That 2/5 is your <b>capstone backlog</b>, priced by the client.' },
        sort: { name: 'REVIEW-DAY MOVES', prompt: 'Sort the showcase behaviours:', g: 'PROFESSIONAL \ud83d\udfe2', r: 'AMATEUR HOUR \ud83d\udd34', intro: 'GREEN = earns trust. RED = burns it.', items: ['Stating a known limit before the demo hits it|green', 'Blaming the user when the demo breaks|red', 'Writing every criticism down, verbatim|green', 'Demo-only features that don\u2019t really work|red', 'Asking \u201cwhat would make this a 5?\u201d|green', 'Arguing with the score|red'] },
        learned: 'Acceptance reviews: the client scores <b>usefulness, safety, norms</b> \u2014 and criticism becomes a priced backlog.', take: 'Semester 4: finish, harden, hand over \u2014 then defend it in public. The backlog you just received is the map.' },
    ] },
    { name: 'Capstone & Citizenship', mods: [
      { n: '27\u201330', name: 'Capstone Completion', act: 'Finish, harden, and hand over the community project \u2014 with documentation and a maintenance / retirement plan.', hook: 'Handover to \u27e8your community client\u27e9', actShort: 'Finish, harden, hand over',
        sign: 'circle', glyph: 'SHIP', h: 'Finished means it lives without you', lt: 'CAPSTONE COMPLETION',
        p: ['Four weeks to make it real: burn down the Mid-Showcase backlog, then <strong>harden</strong> \u2014 the boring heroics: what happens on a power cut, a wrong input, a volunteer who quits? Systems that survive are systems that planned for bad days.', 'Then the part almost everyone skips: <strong>handover</strong>. The client runs it without you \u2014 trained operators, plain-language docs, a maintenance plan (who fixes, who pays) and even a <strong>retirement plan</strong>: when it should be switched off, and what happens to its data. Software that can die gracefully was engineered by adults.'],
        ex: { t: 'Handover kit', i: ['g|Client operators trained \u2014 watched running it WITHOUT you', 'g|Docs + model card, in the client\u2019s languages', 'g|Maintenance: named fixer, spare parts, small budget', 'g|Retirement: shutdown criteria + data deletion plan', 'b|\u201cCall us if it breaks\u201d \u2014 you graduate; the system stays'] },
        co: ['The bus test', 'If your whole team vanished tomorrow, does the co-op\u2019s helper keep helping? Handover is engineering for your own absence.', true],
        build: 'Handover plan. PERSONA: outgoing tech lead. REQUEST: plan the four weeks \u2014 backlog, hardening, training, handover. OUTPUT: week-by-week goals, the operator-training session design, and the retirement criteria. CHECK: the \u201cbus test\u201d \u2014 the client runs a full cycle solo before you sign off.',
        quiz: { q: 'Week 3: tempting new feature vs. finishing the operator training. The capstone answer?', o: ['A|Feature \u2014 impressiveness wins defenses', 'B|Training \u2014 a system the client can\u2019t run without you is an unfinished system|1', 'C|Do both badly'], rf: 'Capstone grades on what SURVIVES handover. An untrained operator turns your feature into e-waste.', wf: 'Impressive-but-orphaned dies in a month. <b>Handover is the deliverable</b> \u2014 the training wins.' },
        learned: 'Completion as adults define it: <b>hardened, documented, handed over</b> \u2014 with maintenance and a graceful retirement plan.', take: 'Next: Mentor Day. You teach the next generation \u2014 the final proof you own what you know.' },
      { n: 31, name: 'Mentor Day', act: 'Teach one Junior Cadet session each \u2014 teaching as mastery assessment.', hook: 'You teach \u27e8next year\u2019s Cadets\u27e9', actShort: 'Teach a Cadet session solo',
        sign: 'circle', glyph: 'TEACH', h: 'You truly know it when a 9-year-old gets it', lt: 'MENTOR DAY',
        p: ['Today you run one <strong>Junior Cadet session</strong> \u2014 solo. Pixel grids, human classifiers, the Kindness Test: take a module you once sat through and make it land for 9-year-olds. No jargon shield: if you can\u2019t explain gradient descent as hill-walking, you don\u2019t own it yet.', 'Mentoring rules: <strong>questions before answers</strong> (let them discover), celebrate their mistakes (Museum-style), and watch for the quiet kid \u2014 your session succeeds when the LEAST confident Cadet leaves taller.'],
        ex: { t: 'Mentor craft', i: ['g|Open with a game, not a definition', 'g|Their mistake \u2192 \u201cbrilliant \u2014 WHY did it happen?\u201d', 'g|Translate every term to playground words first', 'b|Lecturing 9-year-olds about tokenization \u2014 read the room'] },
        co: ['The mastery loop', 'Cadets learn AI; you learn whether you know AI. Teaching is the only exam that grades both sides at once.'],
        quiz: { q: 'Mid-session a Cadet asks, \u201cbut HOW does the model know a cat?\u201d You freeze on the real answer. What does this reveal?', o: ['A|The Cadet asked wrong', 'B|A gap in YOUR understanding \u2014 found precisely; go re-learn, then answer them tomorrow|1', 'C|Nothing \u2014 skip the question'], rf: '\u201cI\u2019ll find out and tell you tomorrow\u201d is a mentor at full strength. The question was your exam.', wf: 'The Cadet just <b>examined you</b> \u2014 and found the gap. Re-learn it, come back tomorrow. That\u2019s mentorship.' },
        sort: { name: 'MENTOR OR LECTURER?', prompt: 'Sort the session moves:', g: 'MENTOR MOVE \ud83d\udfe2', r: 'LECTURE TRAP \ud83d\udd34', intro: 'GREEN = Cadets discover. RED = Cadets endure.', items: ['\u201cWhat do YOU think the machine sees?\u201d|green', 'Twenty minutes of slides|red', 'A sorting game with real leaves|green', 'Vocabulary quiz first|red', 'Praising the funniest wrong answer|green', 'Answering before anyone can guess|red'] },
        learned: 'Teaching as the final exam: translate, question, celebrate mistakes \u2014 and let Cadets\u2019 questions <b>find your gaps</b>.', take: 'Public Defense next: a panel gets to do to you what that Cadet did. Prepare for the WHY behind every choice.' },
      { n: 32, name: 'Public Defense', act: 'Panel of teacher + community client + external adult. Defend your technical AND ethical choices.', hook: 'External judge: \u27e8librarian, engineer, or official\u27e9', actShort: 'Defend every choice before the panel',
        sign: 'octagon', glyph: 'WHY', h: 'Every choice has a why. Know yours.', lt: 'PUBLIC DEFENSE',
        p: ['The panel: your teacher, your client, and an external adult \u2014 a librarian, engineer or official who owes you nothing. Format: brief demo, then <strong>cross-examination</strong>. Technical (\u201cwhy this rung of the ladder?\u201d), ethical (\u201cwho does it exclude?\u201d), and the killer: \u201cwhat would make you switch it off?\u201d', 'Defense craft: answer the question asked; cite your evidence (gate docs, red-team log, client scores); and deploy the strongest sentence in engineering when true \u2014 <strong>\u201cwe don\u2019t know, and here\u2019s how we\u2019d find out.\u201d</strong> Confident ignorance fails; honest uncertainty passes.'],
        ex: { t: 'Cross-examination survival', i: ['g|Every design choice \u2192 a reason \u2192 a document', 'g|\u201cGood question \u2014 here\u2019s the trade-off we weighed\u201d', 'g|Retirement criteria ready for the switch-off question', 'b|Bluffing an answer to the external judge \u2014 they check'] },
        co: ['Why public?', 'You built with the community\u2019s data and trust \u2014 they\u2019re owed a defense in daylight. Accountability is the last module\u2019s first lesson.'],
        quiz: { q: 'The external judge asks: \u201cUnder what conditions should your system be shut down?\u201d Strongest answer?', o: ['A|\u201cNever \u2014 we built it well\u201d', 'B|Your actual retirement criteria: the conditions, who decides, and what happens to the data|1', 'C|\u201cThat\u2019s the client\u2019s problem now\u201d'], rf: 'Naming your own off-switch is the deepest sign you understand what you built. Panels remember it.', wf: '\u201cNever\u201d fails the exam \u2014 every system has failure conditions. Naming your <b>own off-switch</b> is mastery.' },
        sort: { name: 'DEFENSE ANSWERS', prompt: 'Sort the panel answers:', g: 'PASSES \ud83d\udfe2', r: 'FAILS \ud83d\udd34', intro: 'GREEN = evidence and honesty. RED = bluff and dodge.', items: ['\u201cHere\u2019s the red-team finding and our fix\u201d|green', '\u201cIt\u2019s AI, so it\u2019s objective\u201d|red', '\u201cWe don\u2019t know \u2014 here\u2019s how we\u2019d find out\u201d|green', '\u201cTrust us, it works\u201d|red', '\u201cThe client\u2019s score said 2/5, so we rebuilt it\u201d|green', '\u201cNo one would ever misuse it\u201d|red'] },
        learned: 'Public accountability: defending technical and ethical choices with <b>evidence, trade-offs, and honest uncertainty</b>.', take: 'Two modules left. Next: where all of this can take you \u2014 studies, trades, and responsible-AI paths near home.' },
      { n: 33, name: 'Futures Studio', act: 'Pathways: local further-study routes, vocational links, open-source communities, responsible-AI careers.', hook: '\u27e8Local study & career routes\u27e9', actShort: 'Map your own next route',
        sign: 'rect', glyph: 'NEXT', h: 'The licence is a beginning', lt: 'FUTURES STUDIO',
        p: ['Inventory first: you can audit bias, engineer privacy, run ethics gates, build on any infrastructure, document honestly, teach, and defend in public. Those are <strong>employable skills</strong> \u2014 today you map where they lead FROM HERE: local further-study routes, vocational links, open-source communities, responsible-AI work.', 'And the wider truth: every path needs AI-literate people now \u2014 the nurse who questions the triage tool, the farmer who audits the price app, the clerk who spots the biased form. <strong>Citizenship is a career skill.</strong> Studio output: your one-page pathway plan \u2014 dream route, nearby route, and the next concrete step for each.'],
        ex: { t: 'Pathway plan sections', i: ['g|Skills I proved (with the artifact: card, audit, defense)', 'g|Dream route + the nearest local version of it', 'g|Open-source / community I could join THIS year', 'g|Next concrete step, with a date', 'b|\u201cMove far away or nothing\u201d \u2014 the studio\u2019s job is nearer options'] },
        co: ['Portfolio power', 'Your error report, bias tally, model card and defense aren\u2019t schoolwork \u2014 they\u2019re a portfolio. Real reviewers read exactly these.'],
        build: 'Draft the plan. PERSONA: you, five years out, writing back. REQUEST: map two routes \u2014 dream and nearby \u2014 from your actual skills inventory. OUTPUT: one page \u2014 skills + artifacts, both routes, one community to join, next step with a date. CHECK: show it to one adult in a related field and log their advice.',
        quiz: { q: 'A classmate says: \u201cNo AI jobs in this town, so this was all pointless.\u201d Best Futures Studio answer?', o: ['A|True \u2014 move or forget it', 'B|Every local field \u2014 clinic, farm, council, shop \u2014 now needs people who can question and audit AI; you\u2019re that person here|1', 'C|AI skills only matter in big cities'], rf: 'AI literacy lands where AI lands \u2014 which is everywhere. Being the auditor your town has IS the job.', wf: 'The premise is off: AI is arriving in every local field \u2014 the person who can <b>question and audit</b> it is needed HERE.' },
        learned: 'Your skills mapped to <b>real routes</b> \u2014 study, vocational, open-source, civic \u2014 with a portfolio to prove them.', take: 'One module left: graduation, and handing the road to the next crew. Bring your portfolio \u2014 and your successor\u2019s name.' },
      { n: 34, name: 'Graduation & Handover', act: 'Crew Chiefs induct the next cohort; project artifacts enter the community archive.', hook: 'Artifacts join the \u27e8community archive\u27e9', actShort: 'Induct the next crew; archive the work',
        sign: 'circle', glyph: '\ud83c\udf93', h: 'Crew Chief: the licence with obligations', lt: 'GRADUATION',
        p: ['Module 1: you logged a week of AI touchpoints. Module 34: you\u2019ve shipped a community system, defended it in public, and taught the next generation. Today you become <strong>Crew Chief</strong> \u2014 and the ceremony is a handover, because that\u2019s the discipline you learned.', 'Two acts: your <strong>artifacts enter the community archive</strong> \u2014 error reports, bias tallies, model cards, defense records \u2014 becoming the town\u2019s institutional memory about AI. And you <strong>induct the next cohort</strong>: next year\u2019s Crew learns Hallucination Lab from YOUR error report. The road continues; you\u2019re now the one drawing the map.'],
        ex: { t: 'Ceremony order', i: ['g|Artifact deposit: your work, catalogued in the archive', 'g|Induction: hand your successor their first assignment', 'g|The Crew Chief pledge: verify, disclose, audit, include', 'g|Licence conferred \u2014 revocable, renewable, earned'] },
        co: ['Institutional memory', 'When the next misinformation wave or data-centre proposal hits this town, someone will check the archive \u2014 and find YOUR name on the method.', true],
        quiz: { q: 'Why do your artifacts enter a COMMUNITY archive instead of going home in a folder?', o: ['A|The school needs decorations', 'B|They\u2019re the town\u2019s evidence and methods for future AI questions \u2014 knowledge built on community trust returns to the community|1', 'C|To prove homework was done'], rf: 'Built with the town\u2019s data and trust; returned as the town\u2019s memory. That\u2019s the whole curriculum in one gesture. Congratulations, Chief. \ud83c\udf93', wf: 'Bigger than homework: the archive is <b>institutional memory</b> \u2014 your methods, ready for the town\u2019s next AI question.' },
        learned: 'Everything \u2014 from touchpoint logs to public defense \u2014 sealed the Crew way: <b>documented, archived, handed over</b>.', take: 'Crew Chief is a working title: mentor Cadets, audit what arrives, keep the archive alive. The road is yours now. \ud83d\udee3\ufe0f' },
    ] },
  ],
});
